  return {ground:[37,27,68], fade:3.1, add:false, wmul:1.6, sa:70, splat:0.7, glow:0, pal:'pollock'};
}
const cfg = styleCfg(P.style);

if(!S.g || S.key!==BW+'x'+BH){ S.g=createGraphics(BW,BH); S.g.pixelDensity(1); S.g.colorMode(HSB,360,100,100,100); S.key=BW+'x'+BH; S.fresh=true; }
