if(S.seedUsed!==P.seed || S.styleUsed!==P.style){
  S.seedUsed=P.seed; S.styleUsed=P.style; S.rng=mk((P.seed*2654435761)^0x9e3779b1);
  const R=S.rng;
  let pal;
  if(cfg.pal==='vivid') pal=[[180,72,88],[318,68,92],[45,82,94],[0,0,98],[275,58,86],[12,72,92]];
  else if(cfg.pal==='ink') pal=[[0,0,8],[0,0,8],[0,0,20],[0,0,34]];
  else if(cfg.pal==='neon') pal=[[185,90,100],[315,88,100],[95,88,100],[335,85,100],[52,90,100]];
  else if(cfg.pal==='mono'){ pal=[]; for(let i=0;i<6;i++){ pal.push([P.hue,16+i*11,28+i*12]); } }
  else pal=[[0,0,9],[0,0,9],[42,7,95],[8,84,88],[40,82,86],[218,74,66],[178,58,64]];
  S.pal=pal;
  S.pours=[]; const np=3+((R()*3)|0);
  for(let i=0;i<np;i++) S.pours.push({x:0.12+R()*0.76, spread:0.05+R()*0.16});
  S.fresh=true;
}
if(!S.drips) S.drips=[];
const R=S.rng;

if(S.fresh){ g.noStroke(); g.blendMode(BLEND); g.fill(cfg.ground[0],cfg.ground[1],cfg.ground[2],100); g.rect(0,0,BW,BH); S.fresh=false; S.drips.length=0; }

if(S.lastT==null) S.lastT=K.t;
let dt=K.t-S.lastT; if(!(dt>0)||dt>0.2) dt=0.016; S.lastT=K.t;
const sdt=dt*(0.5+P.speed*1.2);

if(S.lastSec==null||K.section<S.lastSec) S.lastSec=K.section;
if(K.section!==S.lastSec){ S.lastSec=K.section; S.burst=(S.burst||0)+46; }
const hueRot=(P.hue-20)+K.section*14+Math.sin(K.t*0.025)*7;

