    for(let k=0;k<nd;k++){ const rr=wgt*(0.6+R()*1.4); g.fill(d.h,d.s,d.b,sa*0.9); g.ellipse(d.x+(R()-0.5)*wgt*10,d.y+(R()-0.5)*wgt*8,rr,rr); }
  }
  if(d.paint<=0 || d.y>BH+6){ pools.push(d); S.drips.splice(i,1); }
}
if(pools.length){ g.noStroke(); for(const d of pools){ if(d.y>poolY*BH){ const rr=Math.max(2,d.w*wsc*3); g.fill(d.h,d.s,d.b,Math.min(100,cfg.sa*0.6*expo)); g.ellipse(d.x,Math.min(BH-2,d.y),rr*1.6,rr*0.7); } } }
g.blendMode(BLEND);

